#!/usr/bin/env python3
"""Materialize one exact AGOT local postimage pair without touching a repository checkout."""
from __future__ import annotations

import argparse
import copy
import hashlib
import json
import os
import re
import stat
from datetime import datetime, timezone
from pathlib import Path, PurePosixPath
from typing import Any, Iterable, Sequence

COMPONENT_ID = "asoiaf-agot-local-feature-postimage-materializer-v1"
UPSTREAM_COMPONENT_ID = "asoiaf-agot-local-feature-materialization-request-v1"
REQUEST_SCHEMA = "axm-asoiaf-agot-local-feature-materialization-request/1"
REQUEST_STATUS = "PASS_LOCAL_FEATURE_MATERIALIZATION_REQUEST_SEALED_EXECUTION_WITHHELD"
REQUEST_VALIDATION_SCHEMA = "axm-asoiaf-agot-local-feature-materialization-request-validation/1"
REQUEST_VALIDATION_STATUS = "PASS_LOCAL_FEATURE_MATERIALIZATION_REQUEST_VALID_FOR_SEPARATE_EXECUTOR"
REQUEST_HOLD = "LOCAL_FEATURE_POSTIMAGE_MATERIALIZATION_WITHHELD"
AUTHORIZATION_SCHEMA = "axm-asoiaf-agot-local-feature-postimage-materialization-authorization/1"
RECEIPT_SCHEMA = "axm-asoiaf-agot-local-feature-postimage-materialization-receipt/1"
PASS_STATUS = "PASS_LOCAL_FEATURE_POSTIMAGES_MATERIALIZED_WORKTREE_APPLICATION_WITHHELD"
NEXT_HOLD = "LOCAL_FEATURE_WORKTREE_APPLICATION_WITHHELD"
SELF_DIGEST_MARKER = "SELF_DIGESTED_OUTPUT"
REPOSITORY = "BigBirdReturns/axm-canon"
BASE_BRANCH = "main"
CANON_PATH = "asoiaf/public/review/ledger/AGOT_CANON_TRANSACTIONS.ndjson"
GRAPH_PATH = "asoiaf/public/review/ledger/AGOT_GRAPH_TRANSACTIONS.ndjson"
GOVERNED_PATHS = [CANON_PATH, GRAPH_PATH]
MAX_REQUEST_BYTES = 2 * 1024 * 1024
MAX_AUTHORIZATION_BYTES = 256 * 1024
MAX_PREIMAGE_BYTES = 16 * 1024 * 1024
MAX_PROPOSITION_CHARS = 2000
HEX64 = re.compile(r"^[0-9a-f]{64}$")
HEX40 = re.compile(r"^[0-9a-f]{40}$")
FEATURE_BRANCH = re.compile(r"^feature/asoiaf-agot/[a-z0-9][a-z0-9._/-]{2,120}$")
FORBIDDEN_KEYS = {
    "sourcetext",
    "paragraphtext",
    "displayedsource",
    "sourceexcerpt",
    "privateparagraph",
    "booktext",
    "rawsource",
    "sourceprose",
    "privatepayload",
    "sourcebytes",
}


class Refusal(RuntimeError):
    """Fail-closed input, output, or authority refusal."""


def canonical(value: Any) -> bytes:
    return json.dumps(
        value,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")


def digest_bytes(value: bytes) -> str:
    return hashlib.sha256(value).hexdigest()


def digest_object(value: Any) -> str:
    return digest_bytes(canonical(value))


def strict_pairs(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
    result: dict[str, Any] = {}
    for key, value in pairs:
        if key in result:
            raise Refusal(f"duplicate JSON key: {key}")
        result[key] = value
    return result


def normalize_key(key: str) -> str:
    return key.casefold().replace("_", "").replace("-", "")


def walk_keys(value: Any) -> Iterable[str]:
    if isinstance(value, dict):
        for key, child in value.items():
            yield normalize_key(str(key))
            yield from walk_keys(child)
    elif isinstance(value, list):
        for child in value:
            yield from walk_keys(child)


def parse_time(value: Any, label: str) -> datetime:
    text = str(value or "")
    if not text.endswith("Z"):
        raise Refusal(f"{label} must use UTC Z suffix")
    try:
        observed = datetime.fromisoformat(text[:-1] + "+00:00")
    except ValueError as exc:
        raise Refusal(f"{label} is not ISO-8601") from exc
    if observed.tzinfo != timezone.utc:
        raise Refusal(f"{label} must be UTC")
    return observed


def require_named(value: Any, label: str, maximum: int = 200) -> str:
    text = str(value or "").strip()
    if len(text) < 3 or len(text) > maximum:
        raise Refusal(f"{label} missing or out of bounds")
    return text


def require_hex64(value: Any, label: str) -> str:
    text = str(value or "")
    if not HEX64.fullmatch(text):
        raise Refusal(f"{label} must be lowercase SHA-256")
    return text


def require_regular_file(path: Path, label: str, maximum: int) -> bytes:
    try:
        info = path.lstat()
    except FileNotFoundError as exc:
        raise Refusal(f"{label} missing") from exc
    if stat.S_ISLNK(info.st_mode):
        raise Refusal(f"{label} symlink refused")
    if not stat.S_ISREG(info.st_mode):
        raise Refusal(f"{label} must be a regular file")
    if info.st_size > maximum:
        raise Refusal(f"{label} exceeds byte limit")
    return path.read_bytes()


def load_object(path: Path, label: str, maximum: int) -> tuple[dict[str, Any], bytes]:
    raw = require_regular_file(path, label, maximum)
    try:
        value = json.loads(raw.decode("utf-8"), object_pairs_hook=strict_pairs)
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise Refusal(f"{label} is not strict UTF-8 JSON") from exc
    if not isinstance(value, dict):
        raise Refusal(f"{label} must be a JSON object")
    return value, raw


def verify_marker_digest(value: dict[str, Any], field: str, label: str) -> str:
    observed = require_hex64(value.get(field), f"{label} {field}")
    if value.get("selfDigestMethod") != SELF_DIGEST_MARKER:
        raise Refusal(f"{label} self-digest method mismatch")
    candidate = copy.deepcopy(value)
    candidate[field] = SELF_DIGEST_MARKER
    if digest_object(candidate) != observed:
        raise Refusal(f"{label} self-digest mismatch")
    return observed


def validate_ndjson(raw: bytes, label: str) -> None:
    if len(raw) > MAX_PREIMAGE_BYTES:
        raise Refusal(f"{label} exceeds byte limit")
    if not raw:
        return
    if not raw.endswith(b"\n"):
        raise Refusal(f"{label} must end with newline")
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise Refusal(f"{label} must be UTF-8") from exc
    if "\x00" in text:
        raise Refusal(f"{label} contains NUL")
    for index, line in enumerate(text.splitlines(), start=1):
        if not line:
            raise Refusal(f"{label} contains blank NDJSON line")
        try:
            value = json.loads(line, object_pairs_hook=strict_pairs)
        except json.JSONDecodeError as exc:
            raise Refusal(f"{label} line {index} is invalid JSON") from exc
        if not isinstance(value, dict):
            raise Refusal(f"{label} line {index} is not an object")


def resolve_preimage(descriptor: dict[str, Any], path_text: str | None, label: str) -> bytes:
    state = descriptor.get("preimageState")
    if state == "ABSENT":
        if path_text is not None:
            raise Refusal(f"{label} path supplied for absent preimage")
        if descriptor.get("preimageBytes") != 0 or descriptor.get("preimageSha256") not in (None, ""):
            raise Refusal(f"{label} absent preimage descriptor inconsistent")
        return b""
    if state != "PRESENT":
        raise Refusal(f"{label} preimage state invalid")
    if path_text is None:
        raise Refusal(f"{label} preimage path required")
    raw = require_regular_file(Path(path_text), label, MAX_PREIMAGE_BYTES)
    validate_ndjson(raw, label)
    if len(raw) != descriptor.get("preimageBytes"):
        raise Refusal(f"{label} preimage byte count mismatch")
    expected_sha = require_hex64(descriptor.get("preimageSha256"), f"{label} preimage digest")
    if digest_bytes(raw) != expected_sha:
        raise Refusal(f"{label} preimage digest mismatch")
    return raw


def validate_descriptor(
    descriptor: Any,
    path: str,
    preimage_path: str | None,
    label: str,
) -> dict[str, Any]:
    if not isinstance(descriptor, dict) or descriptor.get("path") != path:
        raise Refusal(f"{label} target path mismatch")
    preimage = resolve_preimage(descriptor, preimage_path, label)
    row = descriptor.get("appendRow")
    if not isinstance(row, dict):
        raise Refusal(f"{label} append row missing")
    if FORBIDDEN_KEYS.intersection(walk_keys(row)):
        raise Refusal(f"{label} append row contains private field")
    append = canonical(row) + b"\n"
    if descriptor.get("appendBytes") != len(append):
        raise Refusal(f"{label} append byte count mismatch")
    append_sha = require_hex64(descriptor.get("appendSha256"), f"{label} append digest")
    if digest_bytes(append) != append_sha:
        raise Refusal(f"{label} append digest mismatch")
    postimage = preimage + append
    if descriptor.get("postimageBytes") != len(postimage):
        raise Refusal(f"{label} postimage byte count mismatch")
    postimage_sha = require_hex64(descriptor.get("postimageSha256"), f"{label} postimage digest")
    if digest_bytes(postimage) != postimage_sha:
        raise Refusal(f"{label} postimage digest mismatch")
    return {
        "path": path,
        "preimage": preimage,
        "preimageState": descriptor.get("preimageState"),
        "preimageBytes": len(preimage),
        "preimageSha256": digest_bytes(preimage) if preimage else None,
        "appendRow": row,
        "append": append,
        "appendBytes": len(append),
        "appendSha256": append_sha,
        "postimage": postimage,
        "postimageBytes": len(postimage),
        "postimageSha256": postimage_sha,
    }


def validate_request(
    value: dict[str, Any],
    raw: bytes,
    canon_path: str | None,
    graph_path: str | None,
) -> dict[str, Any]:
    if value.get("schema") != REQUEST_SCHEMA:
        raise Refusal("request schema mismatch")
    if value.get("componentId") != UPSTREAM_COMPONENT_ID:
        raise Refusal("request component mismatch")
    if value.get("status") != REQUEST_STATUS or value.get("nextAuthorityHold") != REQUEST_HOLD:
        raise Refusal("request standing mismatch")
    if FORBIDDEN_KEYS.intersection(walk_keys(value)):
        raise Refusal("private source or payload field refused")
    request_sha = verify_marker_digest(value, "requestSha256", "request")
    request_file_sha = digest_bytes(raw)
    request_id = require_hex64(value.get("requestId"), "requestId")
    candidate_id = require_named(value.get("candidateId"), "candidateId")

    exact = value.get("exactBindings")
    if not isinstance(exact, dict):
        raise Refusal("request exact bindings missing")
    for field in (
        "dispositionReceiptSha256",
        "dispositionReceiptFileSha256",
        "materializationPlanSha256",
        "materializationPlanFileSha256",
        "sourceParagraphSha256",
        "admittedPropositionSha256",
    ):
        require_hex64(exact.get(field), f"request {field}")

    authority = value.get("humanAuthority")
    if not isinstance(authority, dict):
        raise Refusal("request human authority missing")
    reviewer_principal = require_named(authority.get("reviewerPrincipal"), "reviewer principal")
    reviewer_display = require_named(authority.get("reviewerDisplayName"), "reviewer display name")
    disposition_author = require_named(
        authority.get("dispositionAuthorPrincipal"),
        "disposition author principal",
    )
    requester_principal = require_named(authority.get("requesterPrincipal"), "requester principal")
    requester_display = require_named(authority.get("requesterDisplayName"), "requester display name")
    request_authored_at = parse_time(authority.get("requestAuthoredAt"), "request authoredAt")
    if authority.get("machinePrepared") is not True:
        raise Refusal("request machine-prepared standing mismatch")
    for field in (
        "humanActionEvidenceSha256",
        "humanRationaleSha256",
        "requestAuthorizationEvidenceSha256",
    ):
        require_hex64(authority.get(field), f"request authority {field}")
    reasons = authority.get("reasonCodes")
    if not isinstance(reasons, list) or not reasons or len(set(map(str, reasons))) != len(reasons):
        raise Refusal("request reason-code census invalid")

    target = value.get("repositoryTarget")
    if not isinstance(target, dict):
        raise Refusal("repository target missing")
    if target.get("repository") != REPOSITORY or target.get("baseBranch") != BASE_BRANCH:
        raise Refusal("repository target identity mismatch")
    base_commit = str(target.get("expectedBaseCommit") or "")
    if not HEX40.fullmatch(base_commit):
        raise Refusal("expected base commit invalid")
    feature_branch = str(target.get("featureBranch") or "")
    if not FEATURE_BRANCH.fullmatch(feature_branch) or ".." in feature_branch or "//" in feature_branch:
        raise Refusal("feature branch invalid")
    if target.get("targetPaths") != GOVERNED_PATHS:
        raise Refusal("target path set mismatch")

    proposed = value.get("proposedPostimages")
    if not isinstance(proposed, dict) or set(proposed) != {"canon", "graph"}:
        raise Refusal("proposed postimages must contain canon and graph only")
    canon = validate_descriptor(proposed["canon"], CANON_PATH, canon_path, "canon")
    graph = validate_descriptor(proposed["graph"], GRAPH_PATH, graph_path, "graph")

    canon_row = canon["appendRow"]
    graph_row = graph["appendRow"]
    proposition = str(canon_row.get("proposition") or "")
    if not proposition or len(proposition) > MAX_PROPOSITION_CHARS:
        raise Refusal("bounded admitted proposition missing")
    proposition_sha = require_hex64(canon_row.get("propositionSha256"), "canon proposition digest")
    if digest_bytes(proposition.encode("utf-8")) != proposition_sha:
        raise Refusal("canon proposition digest mismatch")
    if proposition_sha != exact["admittedPropositionSha256"]:
        raise Refusal("canon row is not exact admitted proposition")
    if canon_row.get("candidateId") != candidate_id or graph_row.get("candidateId") != candidate_id:
        raise Refusal("append row candidate identity mismatch")
    if canon_row.get("sourceParagraphSha256") != exact["sourceParagraphSha256"]:
        raise Refusal("canon row source binding mismatch")
    proposition_node = graph_row.get("propositionNode")
    source_node = graph_row.get("sourceEvidenceNode")
    if not isinstance(proposition_node, dict) or proposition_node.get("sha256") != proposition_sha:
        raise Refusal("graph proposition node mismatch")
    if not isinstance(source_node, dict) or source_node.get("sha256") != exact["sourceParagraphSha256"]:
        raise Refusal("graph source node mismatch")
    for row in (canon_row, graph_row):
        if row.get("dispositionReceiptSha256") != exact["dispositionReceiptSha256"]:
            raise Refusal("append row disposition binding mismatch")
        if row.get("standing") != "PROPOSED_LOCAL_FEATURE_MATERIALIZATION":
            raise Refusal("append row standing mismatch")
        if (
            row.get("repositoryEffect") != "none"
            or row.get("canonEffect") != "none"
            or row.get("graphEffect") != "none"
        ):
            raise Refusal("append row authority boundary changed")

    boundary = value.get("authorityBoundary")
    expected_boundary = {
        "requestIsNotRepositoryMutation": True,
        "postimageFilesWrittenByRuntime": 0,
        "repositoryFilesWrittenByRuntime": 0,
        "worktreesModifiedByRuntime": 0,
        "commitsCreatedByRuntime": 0,
        "referencesUpdatedByRuntime": 0,
        "remotePushesByRuntime": 0,
        "pullRequestsOpenedByRuntime": 0,
        "privateSourceTextPresent": False,
        "privatePayloadPresent": False,
        "canonEffect": "none",
        "graphEffect": "none",
    }
    if not isinstance(boundary, dict) or any(boundary.get(k) != v for k, v in expected_boundary.items()):
        raise Refusal("request authority boundary changed")

    seed = {
        "candidateId": candidate_id,
        "receiptFileSha256": exact["dispositionReceiptFileSha256"],
        "planFileSha256": exact["materializationPlanFileSha256"],
        "repository": REPOSITORY,
        "expectedBaseCommit": base_commit,
        "featureBranch": feature_branch,
        "canonAppendSha256": canon["appendSha256"],
        "graphAppendSha256": graph["appendSha256"],
        "canonPostimageSha256": canon["postimageSha256"],
        "graphPostimageSha256": graph["postimageSha256"],
    }
    if digest_object(seed) != request_id:
        raise Refusal("request identity mismatch")

    return {
        "requestId": request_id,
        "requestSha256": request_sha,
        "requestFileSha256": request_file_sha,
        "candidateId": candidate_id,
        "exactBindings": copy.deepcopy(exact),
        "reviewerPrincipal": reviewer_principal,
        "reviewerDisplayName": reviewer_display,
        "dispositionAuthorPrincipal": disposition_author,
        "requesterPrincipal": requester_principal,
        "requesterDisplayName": requester_display,
        "requestAuthoredAt": authority["requestAuthoredAt"],
        "requestAuthoredAtParsed": request_authored_at,
        "repository": REPOSITORY,
        "baseBranch": BASE_BRANCH,
        "expectedBaseCommit": base_commit,
        "featureBranch": feature_branch,
        "canon": canon,
        "graph": graph,
    }


def validate_request_validation(value: dict[str, Any], raw: bytes, request: dict[str, Any]) -> dict[str, Any]:
    if value.get("schema") != REQUEST_VALIDATION_SCHEMA:
        raise Refusal("request validation schema mismatch")
    if value.get("status") != REQUEST_VALIDATION_STATUS:
        raise Refusal("request validation status mismatch")
    if value.get("requestId") != request["requestId"]:
        raise Refusal("request validation requestId mismatch")
    if value.get("requestSha256") != request["requestSha256"]:
        raise Refusal("request validation self-digest mismatch")
    if value.get("requestFileSha256") != request["requestFileSha256"]:
        raise Refusal("request validation byte binding mismatch")
    if value.get("candidateId") != request["candidateId"]:
        raise Refusal("request validation candidate mismatch")
    if value.get("validatedTargetPaths") != GOVERNED_PATHS:
        raise Refusal("request validation target path mismatch")
    expected_zero = {
        "postimageFilesWrittenByValidator": 0,
        "repositoryFilesWrittenByValidator": 0,
        "worktreesModifiedByValidator": 0,
        "commitsCreatedByValidator": 0,
        "referencesUpdatedByValidator": 0,
        "remotePushesByValidator": 0,
        "pullRequestsOpenedByValidator": 0,
        "canonEffect": "none",
        "graphEffect": "none",
    }
    if any(value.get(k) != v for k, v in expected_zero.items()):
        raise Refusal("request validation authority boundary changed")
    if FORBIDDEN_KEYS.intersection(walk_keys(value)):
        raise Refusal("request validation contains private field")
    return {
        "validationFileSha256": digest_bytes(raw),
        "validationStatus": value["status"],
    }


def validate_authorization(
    value: dict[str, Any],
    raw: bytes,
    request: dict[str, Any],
    actor: str,
) -> dict[str, Any]:
    if value.get("schema") != AUTHORIZATION_SCHEMA:
        raise Refusal("materialization authorization schema mismatch")
    if FORBIDDEN_KEYS.intersection(walk_keys(value)):
        raise Refusal("materialization authorization contains private field")
    authorization_sha = verify_marker_digest(
        value,
        "authorizationSha256",
        "materialization authorization",
    )
    binding = value.get("requestBinding")
    if not isinstance(binding, dict):
        raise Refusal("authorization request binding missing")
    if binding.get("requestId") != request["requestId"]:
        raise Refusal("authorization requestId mismatch")
    if binding.get("requestSha256") != request["requestSha256"]:
        raise Refusal("authorization request self-digest mismatch")
    if binding.get("requestFileSha256") != request["requestFileSha256"]:
        raise Refusal("authorization request byte binding mismatch")

    authority = value.get("materializerAuthority")
    if not isinstance(authority, dict):
        raise Refusal("materializer authority missing")
    principal = require_named(authority.get("materializerPrincipal"), "materializer principal")
    display = require_named(authority.get("materializerDisplayName"), "materializer display name")
    if require_named(actor, "runtime materializer actor") != principal:
        raise Refusal("runtime materializer actor mismatch")
    if principal in {
        request["requesterPrincipal"],
        request["reviewerPrincipal"],
        request["dispositionAuthorPrincipal"],
    }:
        raise Refusal("materializer actor must be independent of upstream human actors")
    authorized_at = parse_time(authority.get("authorizedAt"), "materialization authorizedAt")
    if authorized_at < request["requestAuthoredAtParsed"]:
        raise Refusal("materialization authorization predates request")
    if authority.get("machineGenerated") is not False:
        raise Refusal("machine-generated materialization authorization refused")
    if authority.get("humanAuthorized") is not True:
        raise Refusal("human materialization authorization required")
    evidence = require_named(
        authority.get("authorizationEvidence"),
        "materialization authorization evidence",
        maximum=2000,
    )

    output_policy = value.get("outputPolicy")
    expected_policy = {
        "outputDirectoryClass": "ISOLATED_EMPTY_DIRECTORY",
        "preserveRepositoryRelativePaths": True,
        "postimageFileCount": 2,
        "receiptOutsideOutputDirectory": True,
    }
    if not isinstance(output_policy, dict) or any(output_policy.get(k) != v for k, v in expected_policy.items()):
        raise Refusal("materialization output policy mismatch")

    boundary = value.get("authorityBoundary")
    expected_boundary = {
        "postimageMaterializationAuthorized": True,
        "repositoryWriteAuthorized": False,
        "worktreeWriteAuthorized": False,
        "liveIndexWriteAuthorized": False,
        "commitAuthorized": False,
        "referenceUpdateAuthorized": False,
        "remotePushAuthorized": False,
        "pullRequestAuthorized": False,
        "canonEffect": "none",
        "graphEffect": "none",
    }
    if not isinstance(boundary, dict) or any(boundary.get(k) != v for k, v in expected_boundary.items()):
        raise Refusal("materialization authorization boundary changed")

    return {
        "authorizationSha256": authorization_sha,
        "authorizationFileSha256": digest_bytes(raw),
        "materializerPrincipal": principal,
        "materializerDisplayName": display,
        "authorizedAt": authority["authorizedAt"],
        "authorizationEvidenceSha256": digest_bytes(evidence.encode("utf-8")),
    }


def ensure_isolated_empty_directory(path: Path) -> Path:
    try:
        info = path.lstat()
    except FileNotFoundError as exc:
        raise Refusal("output directory missing") from exc
    if stat.S_ISLNK(info.st_mode):
        raise Refusal("output directory symlink refused")
    if not stat.S_ISDIR(info.st_mode):
        raise Refusal("output path must be a directory")
    if any(path.iterdir()):
        raise Refusal("output directory must be empty")
    resolved = path.resolve(strict=True)
    for ancestor in (resolved, *resolved.parents):
        marker = ancestor / ".git"
        if marker.exists() or marker.is_symlink():
            raise Refusal("output directory inside Git worktree refused")
    return resolved


def path_inside_git_worktree(path: Path) -> bool:
    resolved = path.resolve(strict=True)
    for ancestor in (resolved, *resolved.parents):
        marker = ancestor / ".git"
        if marker.exists() or marker.is_symlink():
            return True
    return False


def ensure_receipt_path(path: Path, output_root: Path) -> Path:
    if path.exists() or path.is_symlink():
        raise Refusal("receipt output already exists")
    if not path.parent.is_dir() or path.parent.is_symlink():
        raise Refusal("receipt output parent missing or unsafe")
    resolved_parent = path.parent.resolve(strict=True)
    if path_inside_git_worktree(resolved_parent):
        raise Refusal("receipt output inside Git worktree refused")
    resolved = resolved_parent / path.name
    try:
        resolved.relative_to(output_root)
    except ValueError:
        return resolved
    raise Refusal("receipt output must be outside postimage output directory")


def safe_destination(root: Path, relative_text: str) -> Path:
    pure = PurePosixPath(relative_text)
    if pure.is_absolute() or ".." in pure.parts or "\\" in relative_text:
        raise Refusal("unsafe governed output path")
    destination = root.joinpath(*pure.parts)
    resolved_parent = destination.parent.resolve(strict=False)
    try:
        resolved_parent.relative_to(root)
    except ValueError as exc:
        raise Refusal("governed output escaped output directory") from exc
    return destination


def write_exclusive(path: Path, payload: bytes) -> None:
    descriptor = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
    try:
        with os.fdopen(descriptor, "wb", closefd=True) as handle:
            handle.write(payload)
            handle.flush()
            os.fsync(handle.fileno())
    except Exception:
        try:
            path.unlink()
        except FileNotFoundError:
            pass
        raise


def write_json_exclusive(path: Path, value: dict[str, Any]) -> bytes:
    payload = (json.dumps(value, indent=2, ensure_ascii=False, sort_keys=True) + "\n").encode("utf-8")
    write_exclusive(path, payload)
    return payload


def output_file_census(root: Path) -> list[str]:
    return sorted(
        str(path.relative_to(root)).replace(os.sep, "/")
        for path in root.rglob("*")
        if path.is_file()
    )


def build_receipt(
    request: dict[str, Any],
    validation: dict[str, Any],
    authorization: dict[str, Any],
) -> dict[str, Any]:
    receipt: dict[str, Any] = {
        "schema": RECEIPT_SCHEMA,
        "componentId": COMPONENT_ID,
        "status": PASS_STATUS,
        "nextAuthorityHold": NEXT_HOLD,
        "requestId": request["requestId"],
