#!/usr/bin/env python3
"""Apply one validated AGOT patch bundle to a clean local feature worktree only."""
from __future__ import annotations

import argparse, hashlib, json, os, subprocess, tempfile
from pathlib import Path, PurePosixPath
from typing import Any, Iterable, Sequence

COMPONENT = "asoiaf-agot-repository-patch-worktree-executor-v1"
CANON = "asoiaf/public/review/ledger/AGOT_CANON_TRANSACTIONS.ndjson"
GRAPH = "asoiaf/public/review/ledger/AGOT_GRAPH_TRANSACTIONS.ndjson"
ALLOWED = (CANON, GRAPH)
FORBIDDEN_BRANCHES = {"main", "master"}
FORBIDDEN_KEYS = {"sourcetext","paragraphtext","displayedsource","sourceexcerpt","privateparagraph","booktext","copyrightedtext"}

class Refusal(RuntimeError):
    def __init__(self, status: str, detail: str):
        super().__init__(detail); self.status=status; self.detail=detail

def canonical(value: Any) -> bytes:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
def digest(value: Any) -> str: return hashlib.sha256(canonical(value)).hexdigest()
def digest_bytes(value: bytes) -> str: return hashlib.sha256(value).hexdigest()
def load(path: Path) -> Any: return json.loads(path.read_text(encoding="utf-8"))
def norm(value: str) -> str: return value.casefold().replace("_", "").replace("-", "")
def walk(value: Any) -> Iterable[str]:
    if isinstance(value, dict):
        for key, child in value.items():
            yield norm(str(key)); yield from walk(child)
    elif isinstance(value, list):
        for child in value: yield from walk(child)
def refuse_source(*values: Any) -> None:
    if any(FORBIDDEN_KEYS.intersection(walk(value)) for value in values):
        raise Refusal("REFUSE_SOURCE_TEXT_FIELD", "source-text-bearing field is forbidden")
def git(repo: Path, *args: str, check: bool=True) -> subprocess.CompletedProcess[str]:
    result = subprocess.run(["git","-C",str(repo),*args], text=True, capture_output=True, shell=False)
    if check and result.returncode != 0:
        raise Refusal("REFUSE_GIT_STATE", result.stderr.strip() or result.stdout.strip() or "git command failed")
    return result
def self_digest(value: dict[str, Any], field: str, status: str) -> None:
    candidate=dict(value); observed=str(candidate.pop(field, "")); expected=digest(candidate)
    if observed != expected: raise Refusal(status, f"{field} mismatch")
def named(value: Any, label: str) -> str:
    actor=" ".join(str(value or "").split())
    if len(actor)<3 or actor.casefold() in {"actor","human","user","test"}:
        raise Refusal("REFUSE_AUTHORIZATION", f"{label} must be separately named")
