def repository_identity(repo: Path) -> str:
    result=git(repo,"config","--get","remote.origin.url",check=False)
    return result.stdout.strip() or f"local:{repo.resolve()}"
def safe_target(repo: Path, relative: str) -> Path:
    pure=PurePosixPath(relative)
    if pure.is_absolute() or ".." in pure.parts or relative not in ALLOWED:
        raise Refusal("REFUSE_TARGET_PATH", relative)
