def parse_status(repo: Path) -> list[str]:
    paths=[]
    for line in git(repo,"status","--porcelain=v1","--untracked-files=all").stdout.splitlines():
        if len(line)<4: continue
        path=line[3:]
        if " -> " in path: path=path.split(" -> ",1)[1]
        paths.append(path.replace("\\","/"))
    return sorted(paths)
def receipt_outside(repo: Path, receipt: Path) -> None:
    rr=repo.resolve(); rp=receipt.resolve()
    if rr==rp or rr in rp.parents: raise Refusal("REFUSE_RECEIPT_BOUNDARY", "receipt must be outside repository")
def verify_bundle(bundle: Path, validation: dict[str, Any]) -> tuple[dict[str, Any], dict[str, bytes]]:
    manifest=load(bundle/"PATCH_MANIFEST.json")
    refuse_source(manifest, validation)
    if manifest.get("schema") != "axm-asoiaf-agot-repository-patch-manifest/1":
        raise Refusal("REFUSE_PATCH_BUNDLE", "manifest schema")
    if manifest.get("status") != "PASS_REPOSITORY_PATCH_MATERIALIZED_PENDING_HUMAN_PR_REVIEW":
        raise Refusal("REFUSE_PATCH_BUNDLE", "manifest standing")
    self_digest(manifest,"patchManifestSha256","REFUSE_PATCH_BUNDLE")
    if validation.get("status") != "PASS_VALID_FOR_SEPARATE_REPOSITORY_EXECUTOR_AND_PR_REVIEW" or validation.get("passed") is not True:
        raise Refusal("REFUSE_PATCH_BUNDLE", "validation standing")
    outputs=manifest.get("proposedOutputs")
    if not isinstance(outputs,dict) or not all(path in outputs for path in ALLOWED):
        raise Refusal("REFUSE_PATCH_BUNDLE", "proposed output set")
    postimages={}
    for relative in ALLOWED:
        path=bundle/"proposed"/Path(*PurePosixPath(relative).parts)
        if not path.is_file(): raise Refusal("REFUSE_PATCH_BUNDLE", f"missing postimage: {relative}")
        raw=path.read_bytes(); expected=outputs[relative]
        if expected.get("bytes") != len(raw) or expected.get("sha256") != digest_bytes(raw):
            raise Refusal("REFUSE_PATCH_BUNDLE", f"postimage identity: {relative}")
        postimages[relative]=raw
    patch_path=bundle/"repository.patch"
    if not patch_path.is_file(): raise Refusal("REFUSE_PATCH_BUNDLE", "repository.patch missing")
    patch=patch_path.read_bytes(); expected_patch=outputs.get("repository.patch")
    if not isinstance(expected_patch,dict) or expected_patch.get("bytes") != len(patch) or expected_patch.get("sha256") != digest_bytes(patch):
        raise Refusal("REFUSE_PATCH_BUNDLE", "patch identity")
