def verify_authorization(auth: dict[str, Any], manifest: dict[str, Any], repo: Path, head: str, branch: str) -> str:
    refuse_source(auth)
    if auth.get("schema") != "axm-asoiaf-local-worktree-apply-authorization/1": raise Refusal("REFUSE_AUTHORIZATION","schema")
    self_digest(auth,"authorizationSha256","REFUSE_AUTHORIZATION")
    if auth.get("decision") != "apply-to-local-feature-worktree": raise Refusal("REFUSE_AUTHORIZATION","decision")
    if auth.get("patchManifestSha256") != manifest.get("patchManifestSha256"): raise Refusal("REFUSE_AUTHORIZATION","manifest binding")
    if auth.get("targetBaseCommit") != head: raise Refusal("REFUSE_AUTHORIZATION","base commit binding")
    if auth.get("targetBranch") != branch: raise Refusal("REFUSE_AUTHORIZATION","branch binding")
    if auth.get("repositoryIdentity") != repository_identity(repo): raise Refusal("REFUSE_AUTHORIZATION","repository identity")
    if not str(auth.get("reason") or "").strip() or not str(auth.get("nonce") or "").strip(): raise Refusal("REFUSE_AUTHORIZATION","reason or nonce missing")
    actor=named(auth.get("worktreeExecutorActor"),"worktree executor")
    upstream=str(manifest.get("patchExecutorActor") or "").strip()
    if upstream and actor.casefold()==upstream.casefold(): raise Refusal("REFUSE_ACTOR_COLLISION","worktree executor collides with patch executor")
    return actor
def preflight(repo: Path, bundle: Path, validation: dict[str, Any], auth: dict[str, Any]) -> tuple[dict[str, Any], dict[str,bytes], dict[str,bytes]]:
    repo=repo.resolve()
    if not (repo/".git").exists(): raise Refusal("REFUSE_GIT_STATE","repository metadata missing")
    head=git(repo,"rev-parse","HEAD").stdout.strip()
    branch=git(repo,"symbolic-ref","--short","HEAD",check=False).stdout.strip()
    if not branch: raise Refusal("REFUSE_BRANCH_BOUNDARY","detached HEAD")
    if branch in FORBIDDEN_BRANCHES: raise Refusal("REFUSE_BRANCH_BOUNDARY",f"default branch forbidden: {branch}")
    if git(repo,"status","--porcelain=v1","--untracked-files=all").stdout.strip(): raise Refusal("REFUSE_DIRTY_WORKTREE","index or worktree is not clean")
    if git(repo,"diff","--cached","--name-only").stdout.strip(): raise Refusal("REFUSE_LIVE_INDEX","live index is not clean")
    manifest,postimages=verify_bundle(bundle,validation)
    pre=manifest.get("preconditions",{})
    if pre.get("targetBaseCommit") != head: raise Refusal("REFUSE_BASE_COMMIT","patch base commit differs from HEAD")
    actor=verify_authorization(auth,manifest,repo,head,branch)
    preimages={}
    for relative in ALLOWED:
        target=safe_target(repo,relative); raw=target.read_bytes() if target.exists() else b""
        key="canonBeforeSha256" if relative==CANON else "graphBeforeSha256"
        if pre.get(key) != digest_bytes(raw): raise Refusal("REFUSE_PREIMAGE",f"target preimage differs: {relative}")
        preimages[relative]=raw
    result={
      "schema":"axm-asoiaf-agot-local-worktree-patch-preflight/1","componentId":COMPONENT,
      "status":"PASS_LOCAL_FEATURE_WORKTREE_READY_FOR_EXPLICIT_APPLY",
      "repositoryIdentity":repository_identity(repo),"headCommit":head,"branch":branch,
      "patchManifestSha256":manifest["patchManifestSha256"],"worktreeExecutorActor":actor,
      "targetPaths":list(ALLOWED),"preimagesVerified":True,
      "gitIndexModified":False,"gitCommitCreated":False,"localReferenceUpdated":False,
      "remoteEffect":"none","canonEffect":"none","graphEffect":"none",
    }
    result["preflightSha256"]=digest(result)
    return result,postimages,preimages
def replace_transaction(repo: Path, postimages: dict[str,bytes], preimages: dict[str,bytes]) -> None:
    temps: dict[str,Path]={}; replaced=[]
    try:
        for relative,raw in postimages.items():
            target=safe_target(repo,relative); target.parent.mkdir(parents=True,exist_ok=True)
            fd,name=tempfile.mkstemp(prefix=target.name+".",suffix=".tmp",dir=target.parent)
            with os.fdopen(fd,"wb") as handle:
                handle.write(raw); handle.flush(); os.fsync(handle.fileno())
            temps[relative]=Path(name)
        for relative in ALLOWED:
            target=safe_target(repo,relative); os.replace(temps[relative],target); replaced.append(relative)
    except Exception:
        for relative in replaced:
            target=safe_target(repo,relative); raw=preimages[relative]
            if raw:
                target.write_bytes(raw)
            else:
                target.unlink(missing_ok=True)
