    finally:
        for temp in temps.values(): temp.unlink(missing_ok=True)
def diff_check(repo: Path) -> None:
    tracked=git(repo,"diff","--check",check=False)
    if tracked.returncode != 0 or tracked.stdout.strip() or tracked.stderr.strip():
        raise Refusal("REFUSE_DIFF_CHECK",tracked.stdout+tracked.stderr)
