        target=safe_target(repo,relative)
        result=subprocess.run(["git","diff","--no-index","--check","--",os.devnull,str(target)],text=True,capture_output=True,shell=False)
        if result.returncode not in (0,1) or result.stdout.strip() or result.stderr.strip():
            raise Refusal("REFUSE_DIFF_CHECK",result.stdout+result.stderr)
def atomic_receipt(path: Path, value: dict[str,Any]) -> None:
    raw=(json.dumps(value,indent=2,sort_keys=True)+"\n").encode(); path.parent.mkdir(parents=True,exist_ok=True)
