              "preflightSha256":pre["preflightSha256"],"repositoryIdentity":pre["repositoryIdentity"],
              "headCommitUnchanged":head_before,"branch":branch_before,"patchManifestSha256":pre["patchManifestSha256"],
              "changedPaths":changed,"gitDiffCheck":"PASS","gitIndexModified":False,"gitCommitCreated":False,
              "localReferenceUpdated":False,"remotePushExecuted":False,"pullRequestOpened":False,
