          "pullRequestOpened":False,"canonEffect":"none","graphEffect":"none","privateSourceTextPresent":False,"privatePayloadPresent":False},3
    except Exception as exc:
        return {"schema":"axm-asoiaf-agot-local-worktree-patch-refusal/1","componentId":COMPONENT,"status":"REFUSE_UNHANDLED_INPUT","detail":f"{type(exc).__name__}: {exc}",
          "gitIndexModified":False,"gitCommitCreated":False,"localReferenceUpdated":False,"remotePushExecuted":False,
          "pullRequestOpened":False,"canonEffect":"none","graphEffect":"none","privateSourceTextPresent":False,"privatePayloadPresent":False},4
def main(argv: Sequence[str]|None=None) -> int:
    p=argparse.ArgumentParser(description=__doc__); p.add_argument("command",choices=("preflight","apply")); p.add_argument("--repo",required=True)
    p.add_argument("--bundle",required=True); p.add_argument("--validation",required=True); p.add_argument("--authorization",required=True)
    p.add_argument("--receipt",required=True); p.add_argument("--apply",action="store_true"); args=p.parse_args(argv)
